    """Fold the [HB, VALS] partial block of one batch element."""
    batch = tl.program_id(0)
    p_offs = tl.arange(0, HB_PAD)
    j_offs = tl.arange(0, VALS_PAD)
    mask = (p_offs[:, None] < HB) & (j_offs[None, :] < VALS)
    part = tl.load(
        part_ptr + batch * HB * VALS + p_offs[:, None] * VALS + j_offs[None, :],
        mask=mask,
        other=0.0,
    )
    sums = tl.sum(part, axis=0)
    tl.store(
        out_ptr + batch * VALS + j_offs,
        sums.to(out_ptr.dtype.element_ty),
        mask=j_offs < VALS,
    )


